begin;
grant insert,select on pg_temp.test_assertions to sivirinia_billing_reconciler;
insert into auth.users(id,email,email_confirmed_at) values('b1000000-0000-0000-0000-000000000001','billing-owner@example.test',now()),('b1000000-0000-0000-0000-000000000002','billing-other@example.test',now());
insert into public.organizations(id,name) values('b2000000-0000-0000-0000-000000000001','Billing A'),('b2000000-0000-0000-0000-000000000002','Billing B');
insert into public.organization_members(organization_id,user_id,role) values('b2000000-0000-0000-0000-000000000001','b1000000-0000-0000-0000-000000000001','owner'),('b2000000-0000-0000-0000-000000000002','b1000000-0000-0000-0000-000000000002','owner');
set local role authenticated;
select set_config('request.jwt.claim.sub','b1000000-0000-0000-0000-000000000001',true);
select set_config('test.intent',public.create_sandbox_billing_intent('b2000000-0000-0000-0000-000000000001','essential')::text,true);
select pg_temp.assert_eq((select amount_cents from public.billing_intents where id=current_setting('test.intent')::uuid),9700,'Preço vem do catálogo, não do navegador');
select pg_temp.assert_eq((select environment from public.billing_intents where id=current_setting('test.intent')::uuid),'sandbox','Intenção desta implementação é somente sandbox');
select pg_temp.assert_throws($$insert into public.billing_events(organization_id) values('b2000000-0000-0000-0000-000000000001')$$,'42501',null,'Cliente não fabrica eventos financeiros');
select pg_temp.assert_throws($$select sivirinia_internal.apply_sandbox_payment(current_setting('test.intent')::uuid,'event-1','123',9700,'BRL','approved')$$,'42501',null,'Cliente não aprova o próprio pagamento');
select set_config('request.jwt.claim.sub','b1000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_eq((select count(*)::int from public.billing_intents),0,'Outro tenant não lê intenção financeira');
select pg_temp.assert_throws($$select public.create_sandbox_billing_intent('b2000000-0000-0000-0000-000000000001','essential')$$,'P0001','Sem permissão','Outro tenant não cria intenção');
reset role;
set local role sivirinia_billing_reconciler;
select pg_temp.assert_throws($$select * from public.billing_intents$$,'42501',null,'Reconciliador não recebe leitura ampla das tabelas');
select pg_temp.assert_throws($$select sivirinia_internal.apply_sandbox_payment(current_setting('test.intent')::uuid,'event-1','123',100,'BRL','approved')$$,'P0001','Valor ou referência financeira incompatível','Valor adulterado é rejeitado');
select pg_temp.assert_true(sivirinia_internal.apply_sandbox_payment(current_setting('test.intent')::uuid,'event-1','123',9700,'BRL','approved'),'Confirmação sandbox é persistida');
select pg_temp.assert_eq(sivirinia_internal.apply_sandbox_payment(current_setting('test.intent')::uuid,'event-1','123',9700,'BRL','approved'),false,'Reentrega do evento é idempotente');
select pg_temp.assert_eq(sivirinia_internal.apply_sandbox_payment(current_setting('test.intent')::uuid,'event-2','123',9700,'BRL','pending'),false,'Evento pendente tardio não regride aprovação');
select pg_temp.assert_throws($$select sivirinia_internal.apply_sandbox_payment(current_setting('test.intent')::uuid,'event-3','456',9700,'BRL','approved')$$,'P0001','Pagamento incompatível com a intenção','Referência não é reutilizada por outro pagamento');
reset role;
select pg_temp.assert_eq((select count(*)::int from public.billing_events where intent_id=current_setting('test.intent')::uuid),2,'Evento repetido não duplica o ledger');
select pg_temp.assert_eq((select status from public.billing_intents where id=current_setting('test.intent')::uuid),'approved','Estado final não regrediu');
select pg_temp.assert_eq((select plan_id from public.organizations where id='b2000000-0000-0000-0000-000000000001'),'free','Pagamento de teste nunca concede plano comercial real');
set local role sivirinia_billing_reconciler;
select pg_temp.assert_true(sivirinia_internal.apply_sandbox_payment(current_setting('test.intent')::uuid,'event-4','123',9700,'BRL','refunded'),'Reembolso sandbox é registrado');
select pg_temp.assert_eq(sivirinia_internal.apply_sandbox_payment(current_setting('test.intent')::uuid,'event-5','123',9700,'BRL','approved'),false,'Aprovação antiga não desfaz reembolso');
reset role;
select 'ASSERTIONS='||count(*) from pg_temp.test_assertions;
rollback;
